+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 8px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+    z-index: 20;
+}
+
+.emoji-option {
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-option:hover {
+    background: #4f545c;
+}
+
+/* ===== Message Input ===== */
+.message-input {
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 14px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+}
+
+.message-input textarea:focus {
+    box-shadow: 0 0 0 1px #7289da;
+}
+
+.send-btn {
+    background: #7289da;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #677bc4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* ===== Thread Panel ===== */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+}
+
+.thread-header {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    margin-top: 4px;
+    color: #b9bbbe;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
+

